<script setup lang="ts">
const route=useRoute(); const supabase=useSupabaseClient(); const listing=ref<any|null>(null); const loading=ref(true); const errorMessage=ref('')
onMounted(async()=>{try{const {data,error}=await supabase.from('parts').select('*,companies!parts_seller_company_id_fkey(name,phone,email,website,city,state_region,country_code,logo_url),part_images(id,image_url,sort_order)').eq('id',route.params.id).eq('status','active').single();if(error)throw error;listing.value=data}catch(e:any){errorMessage.value=e.message||'Part not found.'}finally{loading.value=false}})
const vehicle=computed(()=>listing.value?[listing.value.vehicle_year,listing.value.vehicle_make,listing.value.vehicle_model,listing.value.vehicle_variant].filter(Boolean).join(' '):''); const images=computed(()=>[...(listing.value?.part_images||[])].sort((a:any,b:any)=>a.sort_order-b.sort_order))
</script>
<template><section class="section"><div class="container"><div v-if="loading" class="card" style="padding:24px;">Loading part…</div><div v-else-if="errorMessage" class="notice error">{{errorMessage}}</div><div v-else-if="listing" class="grid grid-2"><div><div v-if="images.length" class="image-gallery"><img :src="images[0].image_url" class="hero-image"><div v-if="images.length>1" class="image-grid" style="margin-top:12px;"><img v-for="img in images.slice(1)" :key="img.id" :src="img.image_url" style="width:100%;height:110px;object-fit:cover;border-radius:12px;"></div></div><div v-else class="card part-placeholder" style="min-height:440px;font-size:72px;">◫</div></div><div><div class="badge">{{listing.condition}}</div><h1 class="page-title" style="margin-top:14px;">{{listing.title}}</h1><p class="muted" style="font-size:18px;">{{vehicle}}</p><div style="font-size:42px;font-weight:950;margin:20px 0;">{{listing.price==null?'Price on request':`$${Number(listing.price).toFixed(2)} ${listing.currency}`}}</div><div class="card" style="padding:20px;"><div class="grid grid-2"><div><span class="muted">OEM / Part No.</span><br><strong>{{listing.oem_number||'—'}}</strong></div><div><span class="muted">Colour</span><br><strong>{{listing.colour||'—'}}</strong></div><div><span class="muted">Supplier</span><br><strong>{{listing.companies?.name}}</strong></div><div><span class="muted">Location</span><br><strong>{{[listing.city,listing.state_region,listing.country_code].filter(Boolean).join(', ')||'—'}}</strong></div><div><span class="muted">Quantity</span><br><strong>{{listing.quantity}}</strong></div><div><span class="muted">Category</span><br><strong>{{listing.category||'—'}}</strong></div></div></div><p style="line-height:1.7;white-space:pre-wrap;">{{listing.description}}</p><div class="card" style="padding:18px;"><h3 style="margin-top:0;">Supplier Contact</h3><div class="muted">{{listing.companies?.phone||'Phone not listed'}}</div><div class="muted">{{listing.companies?.email||'Email not listed'}}</div><div class="muted">{{listing.companies?.website||''}}</div></div></div></div></div></section></template>
